        }

        if (!_env.hasQualifiedTypeCons(newN)) {
            error(NodeUtil.nameString(newN) + " is undefined.", newN);
            return that;
        }
        return typeConsHandler.value(newN);
    } else {
        if (_env.hasTypeParam(n).isSome()) {
            return variableHandler.value();
        } else {
